{
  "command": "python3 << 'EOF'
import itertools, json
import numpy as np

targets = json.load(open('/workspace/whitebox.json'))['targets']
domains = json.load(open('/workspace/whitebox.json'))['domains']
models = ['development-01','development-06','development-08','development-12']

def pearson(x,y):
    x,y=np.array(x),np.array(y)
    if x.std()==0 or y.std()==0: return 0.0
    return float(np.corrcoef(x,y)[0,1])

for dom, tlist in domains.items():
    print('==', dom, tlist)
    best=[]
    for perm in itertools.permutations(models):
        for vals in [(1.0,0.75,0.55,0.3)]:
            m={p:v for p,v in zip(perm,vals)}
            cors=[]
            for t in tlist:
                tg=targets[t]['scores']
                common=[mo for mo in perm if mo in tg]
                cors.append(pearson([m[mo] for mo in common],[tg[mo] for mo in common]))
            best.append((np.mean(cors), perm, [round(c,3) for c in cors]))
    best.sort(reverse=True)
    for b in best[:6]:
        print(round(b[0],4), [m.replace('development-','') for m in b[1]], b[2])
    print()
EOF",
  "description": "Find optimal measured-score orderings per domain"
}

